fn solve(n: i8) -> bool {
    // Convert the number to a string to easily access each digit
    let digits = n.to_string();
    
    // Check if the first three digits are equal
    let first_three_equal = digits.chars().nth(0) == digits.chars().nth(1) && 
                            digits.chars().nth(1) == digits.chars().nth(2);
    
    // Check if the last three digits are equal
    let last_three_equal = digits.chars().nth(1) == digits.chars().nth(2) && 
                           digits.chars().nth(2) == digits.chars().nth(3);
    
    // Return true if either condition is met
    first_three_equal || last_three_equal
}